?>
<section class="dhcn-panel dhcn-workflow" id="dhcn-workflow" aria-labelledby="dhcn-workflow-title">
  <p class="dhcn-eyebrow">EXPLICIT FUNCTIONAL WORK</p><h2 id="dhcn-workflow-title">Retained forecast and evaluation</h2>
  <p>Read persisted model runs, predictions, outcomes and evaluations for one retained match. Display refresh and local health checks do not submit this work.</p>
  <form method="get" action="index.php" class="dhcn-filter"><input type="hidden" name="option" value="com_dragonhydra"><input type="hidden" name="section" value="prediction"><div class="dhcn-match-input"><label for="dhcn-match-id">Retained match identifier</label><input id="dhcn-match-id" name="match_id" type="text" required pattern="[a-f0-9]{64}" maxlength="64" value="<?= $escape($this->workflowMatchId ?? '') ?>" aria-describedby="dhcn-match-help" autocomplete="off"></div><button class="btn btn-outline-primary" type="submit">Read retained history</button></form>
  <p id="dhcn-match-help" class="dhcn-muted">Open an existing <a href="<?= $escape($route('section=matches')) ?>">match</a> and choose “Read retained forecast and evaluation”, or enter its full identifier.</p>
  <?php if(!empty($center['workflow_error'])): ?><p class="alert alert-warning" role="status"><?= $escape($center['workflow_error']) ?></p>
  <?php elseif(!$workflow): ?><p class="dhcn-limit">Select a match to read its retained history. No forecast is manufactured when history is empty.</p>
  <?php else:$match=$workflow['match']; ?>
    <h3><?= $escape($match['home']) ?> — <?= $escape($match['away']) ?></h3>
    <dl class="dhcn-facts"><div><dt>Match ID</dt><dd><?= $escape($match['id']) ?></dd></div><div><dt>Source / fixture</dt><dd><?= $escape($match['source_id']) ?> / <?= $escape($workflow['fixture_key']) ?></dd></div><div><dt>Competition / date / state</dt><dd><?= $escape($match['competition']) ?> / <?= $escape($match['event_date']) ?> / <?= $escape($match['status']) ?></dd></div><div><dt>History cutoff</dt><dd><?= $escape($workflow['cutoff']) ?></dd></div><div><dt>Target evidence</dt><dd><?= $escape($workflow['target_evidence_id']) ?></dd></div></dl>
    <div class="dhcn-summary"><?php foreach(['models'=>'Model runs','predictions'=>'Predictions','outcomes'=>'Attached outcomes','evaluations'=>'Persisted evaluation metrics'] as $kind=>$name): ?><article><span><?= $name ?></span><strong data-workflow-count="<?= $kind ?>"><?= (int)$workflow['counts'][$kind] ?></strong><small>Retained records for this match</small></article><?php endforeach; ?></div>
    <div class="dhcn-detail-grid"><section><h3>Prospective forecast</h3><p>Explicitly calculate and retain existing statistical models and their ensemble from eligible evidence. These are research estimates, separate from final results.</p>
      <?php if(!$this->canImport): ?><p class="dhcn-limit">Requires the existing Import and synchronize sports data permission.</p>
      <?php elseif(!$workflow['forecast_available']): ?><p class="dhcn-limit">A prospective forecast is unavailable for this match state. Finished results cannot become historical prospective forecasts.</p>
      <?php else: ?><form method="post" action="<?= $escape($route('task=actions.forecast')) ?>"><input type="hidden" name="match_id" value="<?= $escape($match['id']) ?>"><input type="hidden" name="command_key" value="<?= $escape($this->workflowKeys['forecasts']) ?>"><button class="btn btn-primary" type="submit">Create and retain forecast</button><?= HTMLHelper::_('form.token') ?></form><p class="dhcn-muted">Repeated submission in this session reuses this command’s idempotency key and job.</p><?php endif; ?>
    </section><section><h3>Evaluate retained forecast</h3><p>Explicitly attach an eligible later outcome and persist comparable operational metrics. Without an eligible prior prediction and later result, evaluation remains pending.</p>
      <?php if(!$this->canImport): ?><p class="dhcn-limit">Requires the existing Import and synchronize sports data permission.</p>
      <?php else: ?><form method="post" action="<?= $escape($route('task=actions.evaluate')) ?>"><input type="hidden" name="match_id" value="<?= $escape($match['id']) ?>"><input type="hidden" name="command_key" value="<?= $escape($this->workflowKeys['evaluations']) ?>"><button class="btn btn-outline-primary" type="submit">Evaluate retained forecast</button><?= HTMLHelper::_('form.token') ?></form><?php endif; ?>
    </section></div>
    <p class="dhcn-muted">At most 100 records per kind are displayed. Totals include all records returned by the selected-match history.</p>
    <h3>Persisted models and supporting evidence</h3>
    <?php if(!$workflow['models']): ?><p class="dhcn-limit">No model run is retained. On-demand Analysis and persisted forecast history have different scopes.</p><?php else: ?>
      <?php foreach($workflow['models'] as $model): ?><article class="dhcn-model" data-model-record="<?= $escape($model['record_id']) ?>"><h4><?= $escape($model['model_name']) ?> / <?= $escape($model['model_version']) ?></h4>
        <dl class="dhcn-facts"><div><dt>Model record</dt><dd><?= $escape($model['record_id']) ?></dd></div><div><dt>Command / run</dt><dd><?= $escape($model['run_id']) ?></dd></div><div><dt>Input cutoff</dt><dd><?= $escape($model['data_cutoff']) ?></dd></div><div><dt>Generated</dt><dd><?= $escape($model['generated_at'] ?: 'Not recorded') ?></dd></div><div><dt>Persisted / usable</dt><dd><?= $escape($model['received_at']) ?> / <?= $escape($model['usable_at']) ?></dd></div><div><dt>Generating build / version</dt><dd><?= $escape($model['build']['build_id'] ?: 'Not recorded') ?> / <?= $escape($model['build']['version'] ?: 'Not recorded') ?></dd></div><div><dt>Generating source commit</dt><dd><?= $escape($model['build']['source_commit'] ?: 'Not recorded') ?></dd></div><div><dt>Generating installation</dt><dd><?= $escape($model['build']['installation_id'] ?: 'Not recorded') ?></dd></div></dl>
        <details><summary>Input evidence, uncertainty and adaptation</summary><p>Showing <?= count($model['input_evidence_ids']) ?> of <?= (int)$model['input_evidence_count'] ?> input evidence references.</p><ul><?php foreach($model['input_evidence_ids'] as $id): ?><li><?= $escape($id) ?></li><?php endforeach; ?></ul><h4>Uncertainty</h4><?php if(!$model['uncertainty']): ?><p>Not recorded.</p><?php else: ?><ul><?php foreach($model['uncertainty'] as $text): ?><li><?= $escape($text) ?></li><?php endforeach; ?></ul><?php endif; ?><h4>Adaptation</h4><p><?= $escape($model['adaptation_reason'] ?: 'No blocking reason recorded; this does not establish improvement.') ?></p><p>Minimum comparable cases: <?= $escape($model['adaptation_minimum_cases'] ?? 'Not recorded') ?>. Retained performance evidence: <?= count($model['adaptation_evidence_ids']) ?>.</p><ul><?php foreach($model['adaptation_evidence_ids'] as $id): ?><li><?= $escape($id) ?></li><?php endforeach; ?></ul></details>
      </article><?php endforeach; ?>
    <?php endif; ?>
    <h3>Persisted predictions</h3>
    <?php if(!$workflow['predictions']): ?><p class="dhcn-limit">No retained prediction is available. No probability is invented.</p><?php else: ?><div class="table-responsive" tabindex="0" role="region" aria-label="Retained forecast probabilities"><table class="table"><caption>Stored probability fractions shown as percentages; model estimates are not final results.</caption><thead><tr><th scope="col">Prediction / model record</th><th scope="col">Home</th><th scope="col">Draw</th><th scope="col">Away</th><th scope="col">Prediction time</th></tr></thead><tbody><?php foreach($workflow['predictions'] as $prediction): ?><tr><th scope="row"><?= $escape($prediction['record_id']) ?><br><small><?= $escape($prediction['model_run_id']) ?></small></th><?php foreach(['home','draw','away'] as $outcome): ?><td><?= $probability($prediction['probabilities'][$outcome]) ?></td><?php endforeach; ?><td><?= $escape($prediction['predicted_at'] ?: $prediction['received_at']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <h3>Attached outcomes</h3>
    <?php if(!$workflow['outcomes']): ?><p class="dhcn-limit">No eligible later outcome is attached. Operational scoring is pending.</p><?php else: ?><ul><?php foreach($workflow['outcomes'] as $outcome): ?><li><strong><?= $escape($outcome['outcome']) ?></strong> · <?= $escape($outcome['record_id']) ?><br>Source evidence <?= $escape($outcome['source_evidence_id']) ?> · usable <?= $escape($outcome['usable_at']) ?></li><?php endforeach; ?></ul><?php endif; ?>
    <h3>Persisted operational evaluation</h3>
    <?php if(!$workflow['evaluations']): ?><p class="dhcn-limit">No operational evaluation metrics have been persisted for this match. Pending is not accuracy, and a completed job does not establish predictive performance.</p><?php else: ?><div class="table-responsive" tabindex="0" role="region" aria-label="Retained operational evaluation"><table class="table"><caption>Existing retained cohort metrics with original source, competition, period, settlement and sample size.</caption><thead><tr><th scope="col">Record / model</th><th scope="col">Metric / loss</th><th scope="col">Sample size</th><th scope="col">Scope</th><th scope="col">Cutoff</th></tr></thead><tbody><?php foreach($workflow['evaluations'] as $evaluation): ?><tr><th scope="row"><?= $escape($evaluation['record_id']) ?><br><?= $escape($evaluation['model']) ?> / <?= $escape($evaluation['model_version']) ?></th><td><?= $escape($evaluation['metric']) ?> / <?= $escape($evaluation['loss'] ?? 'Not available') ?></td><td><?= $escape($evaluation['sample_size'] ?? 'Not available') ?></td><td><?= $escape(implode(' / ',$evaluation['scope'])) ?></td><td><?= $escape($evaluation['evaluation_cutoff']) ?></td></tr><?php endforeach; ?></tbody></table></div><?php endif; ?>
    <details><summary>Evaluation scope and limitations</summary><p>Present-knowledge historical holdout is a separate retrospective diagnostic, not an operational score for a retained earlier prediction. <?= $escape($workflow['holdout_reason'] ?: 'No diagnostic was requested by this history read.') ?></p><ul><?php foreach($workflow['limitations'] as $text): ?><li><?= $escape($text) ?></li><?php endforeach; ?></ul></details>
  <?php endif; ?>
</section>
